diff --git a/io/io.cpp b/io/io.cpp
index 85f414f..d010bff 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -669,6 +669,51 @@ des_ce array_ce[MAX_CE];
 natl next_ce;

 // ( SOLUZIONE 2025-09-10
+extern "C" natl c_ceasyncread_n(natl id, char *buf, natl quanti)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceasyncread_n: ce non riconosciuto: %u", id);
+		abort_p();
+	}
+	if (quanti == 0) {
+		flog(LOG_WARN, "ceasyncread_n: quanti zero");
+		abort_p();
+	}
+	if (!access(buf, quanti, true)) {
+		flog(LOG_WARN, "ceasyncread_n: buffer non accessibile");
+		abort_p();
+	}
+
+	des_ce *ce = &array_ce[id];
+	sem_wait(ce->mutex);
+
+	natl trid = 0xFFFFFFFF;
+	for (natl i = 0; i < MAX_CE_ASYNC; i++) {
+		if (ce->tr[i].buf == nullptr) {
+			trid = i;
+			break;
+		}
+	}
+
+	if (trid != 0xFFFFFFFF) {
+		ce->tr[trid].buf = buf;
+		ce->tr[trid].quanti = quanti;
+		ce->tr[trid].next = 0xFFFFFFFF;
+		if (ce->last == 0xFFFFFFFF) {
+			ce->last = trid;
+		} else {
+			ce->tr[ce->last].next = trid;
+			ce->last = trid;
+		}
+		if (ce->cur == 0xFFFFFFFF) {
+			ce->cur = trid;
+			outputb(1, ce->iCTL);
+		}
+	}
+
+	sem_signal(ce->mutex);
+	return trid;
+}
 //   SOLUZIONE 2025-09-10 )

 extern "C" void c_cewait(natl id, natl trid)
@@ -705,6 +750,35 @@ extern "C" void c_cewait(natl id, natl trid)
 extern "C" void estern_ce(natq id)
 {
 // ( SOLUZIONE 2025-09-10
+	for (;;) {
+		des_ce *ce = &array_ce[id];
+		sem_wait(ce->mutex);
+		if (ce->cur != 0xFFFFFFFF && ce->tr[ce->cur].buf != nullptr) {
+			char *b = ce->tr[ce->cur].buf;
+			natl q = ce->tr[ce->cur].quanti;
+			sem_signal(ce->mutex);
+			if (q > 0) {
+				paddr p = trasforma(b);
+				*ptr_cast<char>(p) = inputb(ce->iRBR);
+				sem_wait(ce->mutex);
+				ce->tr[ce->cur].buf++;
+				ce->tr[ce->cur].quanti--;
+				if (ce->tr[ce->cur].quanti == 0) {
+					natl next = ce->tr[ce->cur].next;
+					ce->cur = next;
+					if (next == 0xFFFFFFFF) {
+						outputb(0, ce->iCTL);
+					}
+					if (ce->waiting > 0) {
+						ce->waiting--;
+						sem_signal(ce->sync);
+					}
+				}
+			}
+		}
+		sem_signal(ce->mutex);
+		wfi();
+	}
 //   SOLUZIONE 2025-09-10 )
 }

